        $c2 = $c->getNewCriterion(SeriePeer::DEPENDENCIA_ID, $dependencia_id);
        $c3 = $c->getNewCriterion(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_conectado);
        $c3->addOr($c2);
        $c->add($c3);*/
      }
      //*********************************************************************
      $c->add(SeriePeer::DEPENDENCIA_ID,$id_seleccion);
      $c->addAscendingOrderByColumn(SeriePeer::DESCRIPCION);
      $series = SeriePeer::doSelect($c);
      //*********************************************************************
      foreach($series as $item){
        $icon_class = 'folder';
        $item_nombre = trim($item->getDescripcion());
        $item_compuesto = !empty($item->getCodigo()) ? trim($item->getCodigo())." - ".$item_nombre : $item_nombre;
        $nodes[] = array('id' => $seriestrmd5.$item->getPrimaryKey(),'label' => ($item_compuesto),'inode' => true, 'open' => false,'icon' => $icon_class, 
                        'checkbox' => false, 'radio' => false, 'type' => 'Folder', 'random' => mt_rand(200, 2999));
      }
      //*********************************************************************
      //$nodes = array('branch' => $branchs);
    }elseif(substr_count($branch, $seriestrmd5)){
      $c = new Criteria();
      $c->setDistinct();
      //*********************************************************************
      $id_seleccion = preg_replace("/$seriestrmd5/", "", $branch);
      //*********************************************************************
      $c->add(SubseriePeer::SERIE_ID,$id_seleccion);
      $c->addAscendingOrderByColumn(SubseriePeer::DESCRIPCION);
      $objects_list = SubseriePeer::doSelect($c);
      //*********************************************************************
      foreach($objects_list as $item){
        $icon_class = 'file';
        $item_nombre = trim($item->getDescripcion());
        $item_compuesto = !empty($item->getCodigo()) ? trim($item->getCodigo())." - ".$item_nombre : $item_nombre;
