    $this->filtros_consulta = "";
    //*************************************************************************************************
    //ARCHIVO ACTUAL
    $this->localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');
    $c->add(TransferenciaPeer::DESTINOTRANSFERENCIA_ID, $this->getRequestParameter('localizacionunidaddocumental_id'));
    $this->filtros_consulta .= "&localizacionunidaddocumental_id=" . $this->localizacion;
    //ESTADO TRANSFERENCIA
    $estado_transferencia = $this->getRequestParameter('estado_transferencia');
    if ($estado_transferencia != "") {
      $c->add(TransferenciaPeer::ESTADOTRANSFERENCIA_ID, $estado_transferencia);
      $this->filtros_consulta .= "&estado_transferencia=" . $estado_transferencia;
    }
    //*************************************************************************************************
    // ORIGEN TRANSFERENCIA
    $origen_transferencia = $this->getRequestParameter('origen_transferencia');
    if ($origen_transferencia != "") {
      $c->add(TransferenciaPeer::ORIGENTRANSFERENCIAID, $origen_transferencia);
      $this->filtros_consulta .= "&origen_transferencia=" . $origen_transferencia;
    }
    //*************************************************************************************************
    // CONSULTA FECHA CREACION
    $fecha_creacion_inicial = $this->getRequestParameter('desde');
    $fecha_creacion_final = $this->getRequestParameter('hasta');
    if ($fecha_creacion_inicial != "") {
      if ($fecha_creacion_final == "") {
        $fecha_creacion_final = $fecha_creacion_inicial;
      }
      $c->add(TransferenciaPeer::FECHA_CREACION, $fecha_creacion_inicial . ' 00:00:00', Criteria::GREATER_EQUAL);
      $c->addAnd(TransferenciaPeer::FECHA_CREACION, $fecha_creacion_final . ' 23:59:59', Criteria::LESS_EQUAL);
      $this->filtros_consulta .= "&desde=" . str_replace("/", "-", $fecha_creacion_inicial);
      $this->filtros_consulta .= "&hasta=" . str_replace("/", "-", $fecha_creacion_final);
    }
    //*************************************************************************************************
    // CONSULTA USUARIO QUE SOLICITA VALIDANDO EL PERMISO DE LISTAR TODAS LAS COMUNICACIONES
    $solicitado_por = $this->getRequestParameter('usuario_solicita');
    if ($this->tienePrilegio("LISTAR_TODAS_TRANSFERENCIAS")) {
      if ($solicitado_por != "") {
        $c->addJoin(TransferenciaPeer::TRANSFERENCIA_ID, UsuarioTransferenciaPeer::TRANSFERENCIA_ID);
        $c->add(UsuarioTransferenciaPeer::USUARIO_ID, $solicitado_por);
        $c->add(UsuarioTransferenciaPeer::ROLUSUARIOTRANSFERENCIA_ID, 1);
        $this->filtros_consulta .= "&usuario_solicita=" . $solicitado_por;
      }
    } else {
      $c->addJoin(TransferenciaPeer::TRANSFERENCIA_ID, UsuarioTransferenciaPeer::TRANSFERENCIA_ID);
      $c->add(UsuarioTransferenciaPeer::USUARIO_ID, $usuariologuiado);
      $c->add(UsuarioTransferenciaPeer::ROLUSUARIOTRANSFERENCIA_ID, 1);
      $this->filtros_consulta .= "&usuario_solicita=" . $solicitado_por;
    }
    //*************************************************************************************************	
    //CONSECUTIVO DE LA TRANSFERENCIA
    $num_trans = $this->getRequestParameter('numTransferencia');
    if ($num_trans != "") {
      $c->add(TransferenciaPeer::TRANSFERENCIA_ID, $num_trans);
      //$c->add(UsuarioTransferenciaPeer::USUARIO_ID, $solicitado_por);
      //$c->add(UsuarioTransferenciaPeer::ROLUSUARIOTRANSFERENCIA_ID, 1);
      $this->filtros_consulta .= "&numTransferencia=" . $num_trans;
    }
    //*************************************************************************************************
    //POR MARCA
    $marcado = $this->getRequestParameter('marcado');
    if ($marcado != "") {
      $c->add(TransferenciaPeer::MARCA, $usuariologuiado);
      $this->filtros_consulta .= "&marcado=" . $marcado;
    }
    //*************************************************************************************************
    //Consulta por Codigo De Barras.
    $cod_barras = $this->getRequestParameter('codigo_barras');
    if ($cod_barras != "") {
      $c->addJoin(TransferenciaPeer::UNIDADDOCUMENTAL_ID, UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
      $c->add(UnidadDocumentalPeer::CODIGO_BARRAS, '%' . $cod_barras . '%', Criteria::LIKE);
      //$c->add(UnidadDocumentalPeer::CODIGO_BARRAS, '%'.$cod_barras.'%',Criteria::LIKE);		
      $this->filtros_consulta .= "&codigo_barras=" . $cod_barras;
    }
    //*************************************************************************************************
    $c->addDescendingOrderByColumn(TransferenciaPeer::TRANSFERENCIA_ID);
    $pager = new sfPropelPager('Transferencia', 10);
    $pager->setCriteria($c);
    $pager->setPage($this->getRequestParameter('page', 1));
    $pager->init();
    $this->pager = $pager;
    //*************************************************************************************************
    $this->mensajeListaVacia = ConsultaPermisoHelper::MSG_SIN_REGISTROS;
    if ($pager->getNbResults() == 0 && (trim($cod_barras) || trim($num_trans))) {
      $cSinPermiso = new Criteria();
      if (trim($cod_barras)) {
        $cSinPermiso->addJoin(TransferenciaPeer::UNIDADDOCUMENTAL_ID, UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
        $cSinPermiso->add(UnidadDocumentalPeer::CODIGO_BARRAS, '%'.trim($cod_barras).'%', Criteria::LIKE);
      } else {
        $cSinPermiso->add(TransferenciaPeer::TRANSFERENCIA_ID, trim($num_trans));
      }
      $countSinPermiso = TransferenciaPeer::doCount($cSinPermiso);
      $this->mensajeListaVacia = ConsultaPermisoHelper::mensajeListaVacia($countSinPermiso);
    }
    //$this->filtros_consulta = $parametros_consulta;
    /**************************************************************************************************************/
    $this->parametroFormatoDig   = ParametroPeer::retrieveByPk(31)->getValortexto();
    $this->internaDirApacheDig   = ParametroPeer::retrieveByPk(26)->getValortexto() . ParametroPeer::retrieveByPk(15)->getValortexto();
    $this->recibidaDirApacheDig  = ParametroPeer::retrieveByPk(28)->getValortexto() . ParametroPeer::retrieveByPk(14)->getValortexto();
    $this->enviadaDirApacheDig   = ParametroPeer::retrieveByPk(30)->getValortexto() . ParametroPeer::retrieveByPk(13)->getValortexto();
    /**************************************************************************************************************/
    $this->view_link_expediente   = $this->tienePrilegio("VER_LINK_UNIDAD_DOCUMENTAL");
    /**************************************************************************************************************/
  }

