    $cominterna_id  = $this->getRequestParameter('cominterna_id');
    $comenviada_id  = $this->getRequestParameter('comenviada_id');
    $documentacion_id  = $this->getRequestParameter('documentacion_id');
    $factura_id = $this->getRequestParameter('factura_id');
    //*********************************************************************
    $this->field_name = "";
    $this->field_value = "";
    if (!empty($comrecibida_id)) {
      $this->field_name = 'comrecibida_id';
