  public function executeUpdate()
  {
    if (!$this->getRequestParameter('transferencia_id')) {
      $transferencia = new Transferencia();
	  //*************************************************************************************************
	  $transferencia_anterior = clone $transferencia;
	  //*************************************************************************************************
      $transferencia->setFechaCreacion(date('Y-m-d G:i:s'));
    } else {
      $transferencia = TransferenciaPeer::retrieveByPk($this->getRequestParameter('transferencia_id'));
	  //*************************************************************************************************
	  $transferencia_anterior = clone $transferencia;
	  //*************************************************************************************************
      $this->forward404Unless($transferencia);
    }
    //***************************************************************************************************
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $transferencia->setVinculadaId($this->getRequestParameter('vinculada_id') ? $this->getRequestParameter('vinculada_id') : null);
    //***************************************************************************************************
    if ($transferencia->getDestinotransferenciaId() != 1) {
      $transferencia->setEstadotransferenciaId(1);
    } else {
      $transferencia->setEstadotransferenciaId(2);
    }
    //***************************************************************************************************
    $transferencia->setUnidaddocumentalId($this->getRequestParameter('unidaddocumental_id'));
    $transferencia->setOrigentransferenciaid($this->getRequestParameter('origentransferenciaid') ? $this->getRequestParameter('origentransferenciaid') : null);
    $transferencia->setComenviadaId($this->getRequestParameter('comenviada_id') ? $this->getRequestParameter('comenviada_id') : null);
    $transferencia->setCominternaId($this->getRequestParameter('cominterna_id') ? $this->getRequestParameter('cominterna_id') : null);
    $transferencia->setComrecibidaId($this->getRequestParameter('comrecibida_id') ? $this->getRequestParameter('comrecibida_id') : null);
    $transferencia->setDocumentacionId($this->getRequestParameter('documentacion_id') ? $this->getRequestParameter('documentacion_id') : null);
    $transferencia->setFacturaId($this->getRequestParameter('factura_id') ? $this->getRequestParameter('factura_id') : null);
    $transferencia->setTipodocumentalId($this->getRequestParameter('tipo_documental') ? $this->getRequestParameter('tipo_documental') : null);
    $transferencia->setDestinotransferenciaId($this->getRequestParameter('destinotransferencia_id') ? $this->getRequestParameter('destinotransferencia_id') : null);
    //***************************************************************************************************
    // Control de obligatoriedad de "Requiere respuesta" al archivar (solo Comunicaciones Recibidas)
    if ($transferencia->getOrigentransferenciaid() == 2 && trim($this->getRequestParameter('comrecibida_id'))) {
      $com_recibida = ComRecibidaPeer::retrieveByPk(trim($this->getRequestParameter('comrecibida_id')));
      if ($com_recibida) {
        $requiereRespuestaParam = $this->getRequestParameter('requiere_respuesta');
        $requiereRespuesta = ($requiereRespuestaParam === null || $requiereRespuestaParam === '') ? null : (bool) $requiereRespuestaParam;
        $observacion = trim($this->getRequestParameter('obs_no_respuesta'));
        $errorRequiereRespuesta = RequiereRespuestaValidator::validar($requiereRespuesta, $observacion);
        if ($errorRequiereRespuesta) {
          $this->getUser()->setFlash('messages_error', $errorRequiereRespuesta);

          return $this->redirect($this->getRequest()->getScriptName().'/transferencia/create?comrecibida_id='.$com_recibida->getPrimaryKey().'&unidaddocumental_id='.trim($this->getRequestParameter('unidaddocumental_id')).'&origen_transferencia='.trim($this->getRequestParameter('origen_transferencia')));
        }
        $com_recibida_anterior = clone $com_recibida;
        $com_recibida->setRequiereRespuesta($requiereRespuesta);
        if (!$requiereRespuesta) {
          $usuarioActorRequiereResp = UsuarioPeer::retrieveByPk($usuariologuiado);
          $com_recibida->setObsNoRespuesta(RequiereRespuestaValidator::construirObservacionConTrazabilidad($observacion, $usuarioActorRequiereResp));
        }
        $com_recibida->save();
        AuditLogPeer::guardarAuditoriaLite('ComRecibida', $com_recibida_anterior, $com_recibida, ModulesEnable::ComRecibida, $com_recibida->getRadicado(), $usuariologuiado);
      }
    }
    //***************************************************************************************************
    $transferencia->save();
    //***************************************************************************************************
	AuditLogPeer::guardarAuditoriaLite("Transferencia",$transferencia_anterior,$transferencia,ModulesEnable::Archivo,$transferencia->getTransferenciaId(),$usuariologuiado);
	//***************************************************************************************************
    // USUARIO TRANSFERENCIA
    TransferenciaPeer::createUserTransferencia($transferencia, $usuariologuiado, 1);
    //***************************************************************************************************
    // UNIDAD DOCUMENTAL
    if (trim($this->getRequestParameter('unidaddocumental_id'))) {
      $unidad_documental = UnidadDocumentalPeer::retrieveByPK(trim($this->getRequestParameter('unidaddocumental_id')));
      $unidad_documental_anterior = clone $unidad_documental;
		  //*************************************************************************************************
      $unidad_documental->setFechaCierre(trim($this->getRequestParameter('fecha_cierre')) ? trim($this->getRequestParameter('fecha_cierre')) : $unidad_documental->getFechaCierre());
      $unidad_documental->setFolios(!empty($this->getRequestParameter('folios')) ? trim($this->getRequestParameter('folios')) : $unidad_documental->getFolios());
      if ($transferencia->getDestinotransferenciaId() != 1) {
        $unidad_documental->setEstadoTransferencia(1);
      } else {
        $unidad_documental->setEstadoTransferencia(0);
      }
      $unidad_documental->save();
      //*************************************************************************************************
      AuditLogPeer::guardarAuditoriaLite("UnidadDocumental",$unidad_documental_anterior,$unidad_documental,ModulesEnable::Archivo,$unidad_documental->getCodigoBarras(),$usuariologuiado);
      //*************************************************************************************************
      $transferencia->transferirGestion($usuariologuiado);
      //*************************************************************************************************
      if ($transferencia->getDestinotransferenciaId() == 1) {
        TransferenciaPeer::createUserTransferencia($transferencia,$usuariologuiado);
      }
    }
    //***************************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/transferencia/show?transferencia_id=' . $transferencia->getTransferenciaId());
  }

  public function executeTransferir()
  {
    if (!$this->getRequestParameter('transferencia_id')) {
      $transferencia = new Transferencia();
    } else {
      $transferencia = TransferenciaPeer::retrieveByPk($this->getRequestParameter('transferencia_id'));
      $this->forward404Unless($transferencia);
    }
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    //******************************************************************************************
    $transferencia->setEstadotransferenciaId(2);
    $transferencia->setFechaAceptacion(date('Y-m-d G:i:s'));
    $transferencia->save();
    //******************************************************************************************
    TransferenciaPeer::createUserTransferencia($transferencia,$usuariologuiado);
    //******************************************************************************************
    // TRANSFERENCIA DESDE COMUNICACIONES O VINCULAR
    if ($transferencia->getOrigentransferenciaid() <= 4 || $transferencia->getOrigentransferenciaid() == 7) {
      $this->transferenciaComunicaciones($transferencia);
      $transferencia->enviarAlertas();
    } else {
      $ubicacion = $this->getRequestParameter('ubicacion');
      $this->transferenciaArchivos($transferencia, $ubicacion);
      $transferencia->enviarAlertas();
    }
    //******************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/transferencia/show?transferencia_id=' . $transferencia->getTransferenciaId());
  }

