  public function executeAcceptAll(sfWebRequest $request)
  {
    $currentForm = "TRANSFERENCIA_ACEPTAR";
    $this->verificaPrilegio($currentForm);
  }

  public function executeTransferAll()
  {
    $currentForm = "TRANSFERENCIA_ACEPTAR";
    $this->verificaPrilegio($currentForm);
    //**********************************************************************************************
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $nueva_ubicacion = $this->getRequestParameter('ubicacion');
    //**********************************************************************************************
    $c = new Criteria();
    $c->add(TransferenciaPeer::MARCA, $usuariologuiado);
    $c->add(TransferenciaPeer::ESTADOTRANSFERENCIA_ID, 1);
    $result = TransferenciaPeer::doSelect($c);
    //**********************************************************************************************
    foreach ($result as $transferencia) {
      if ($transferencia->getEstadotransferenciaId() == 1) {
        //se crea el usuario q acepta la transferenica
        TransferenciaPeer::createUserTransferencia($transferencia, $usuariologuiado);
        //se actualiza estado y fecha de la transferencia
        $this->updateTransferencia($transferencia);
        // TRANSFERENCIA DESDE COMUNICACIONES O VINCULAR
        if ($transferencia->getOrigentransferenciaid() <= 4 || $transferencia->getOrigentransferenciaid() == 7) {
          $this->transferenciaComunicaciones($transferencia);
        } else {
          $this->transferenciaArchivos($transferencia, $nueva_ubicacion);
        }
      }
    }
    //**********************************************************************************************
  }

  public function executeMarcar()
  {
    $marcar = 0;
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $transferencia = TransferenciaPeer::retrieveByPK($this->getRequestParameter('transferencia_id'));
    if ($transferencia->getMarca() == 0 || $transferencia->getMarca() != $usuariologuiado) {
      $marcar = $usuariologuiado;
    }
    $transferencia->setMarca($marcar);
    $transferencia->save();
  }

  public function executeUpdateRechazarMarcados()
  {
    $currentForm = "TRANSFERENCIA_RECHAZAR";
    $this->verificaPrilegioCerrar($currentForm);
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    //$observaciones = $this->getRequestParameter('observaciones');
    $localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');
    if ($localizacion) {
      $c = new Criteria();
      $c->add(TransferenciaPeer::MARCA, $usuariologuiado);
      $c->add(TransferenciaPeer::ESTADOTRANSFERENCIA_ID, 1);
      $c->add(TransferenciaPeer::DESTINOTRANSFERENCIA_ID, $localizacion);
      $transferencias_marcadas = TransferenciaPeer::doSelect($c);
      foreach ($transferencias_marcadas as $transferencia) {
        if ($transferencia->getEstadotransferenciaId() == 1) {
          $this->rechazarTransferencia($transferencia);
          $this->envioMailRechazo($transferencia);
        }
      }
    }
  }

  public function executeUpdateRechazar()
  {
    if (!$this->getRequestParameter('transferencia_id')) {
      $transferencia = new Transferencia();
    } else {
      $transferencia = TransferenciaPeer::retrieveByPk($this->getRequestParameter('transferencia_id'));
      $this->forward404Unless($transferencia);
    }
    //******************************************************************************************
    $transferencia->setEstadotransferenciaId(3);
    $transferencia->setFechaAceptacion(date('Y-m-d G:i:s'));
    //$transferencia->save();
    //******************************************************************************************
    // USUARIO TRANSFERENCIA
    $usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $user_transfer = new UsuarioTransferencia();
    $user_transfer->setRolusuariotransferenciaId(2);
    $user_transfer->setTransferenciaId($transferencia->getTransferenciaId());
    $user_transfer->setUsuarioId($usuario_conectado);
    $user_transfer->save();
    //******************************************************************************************
    // TRANSFERENCIA DESDE COMUNICACIONES O VINCULAR
    if ($transferencia->getOrigentransferenciaid() == 4) {
      // VINCULADA
      $vinculada = VinculadaPeer::retrieveByPK($transferencia->getVinculadaId());
      $vinculada->setAceptado(2);
      $vinculada->save();
    } else {
      // SI LA TRANSFERENCIA ES ENTRE ARCHIVOS
      // ACTUALIZACION DE LA UNIDAD DOCUMENTAL
      $unidad_documental = UnidadDocumentalPeer::retrieveByPk($transferencia->getUnidaddocumentalId());
      $unidad_documental->setEstadoTransferencia(null);
      $unidad_documental->save();
    }
    //******************************************************************************************
    $transferencia->setMarca(0);
    $transferencia->setObservaciones($this->getRequestParameter('observaciones'));
    $transferencia->save();
    //******************************************************************************************
    // USUARIO SOLICITA
    $c = new Criteria();
    $c->add(UsuarioTransferenciaPeer::ROLUSUARIOTRANSFERENCIA_ID, 1);
    $c->add(UsuarioTransferenciaPeer::TRANSFERENCIA_ID, $this->getRequestParameter('transferencia_id'));
    $usuario_solicita = UsuarioTransferenciaPeer::doSelectOne($c);
    //******************************************************************************************
    if ($usuario_solicita->getPrimaryKey()) {
      $transferencia->envioEmail($usuario_solicita->getUsuario());
    }
    //******************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/transferencia/show?transferencia_id=' . $transferencia->getTransferenciaId());
  }

  public function executeDelete()
  {
    $transferencia = TransferenciaPeer::retrieveByPk($this->getRequestParameter('transferencia_id'));
    $this->forward404Unless($transferencia);
    $transferencia->delete();
    return $this->redirect($this->getRequest()->getScriptName().'/transferencia/list');
  }

  public function  rechazarTransferencia(Transferencia $transferencia)
  {
    $transferencia->setEstadotransferenciaId(3);
    $transferencia->setFechaAceptacion(date('Y-m-d G:i:s'));
    // USUARIO TRANSFERENCIA
    $usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $user_transfer = new UsuarioTransferencia();
    $user_transfer->setRolusuariotransferenciaId(2);
    $user_transfer->setTransferenciaId($transferencia->getTransferenciaId());
    $user_transfer->setUsuarioId($usuario_conectado);
    $user_transfer->save();
    //*********************************************************************************
    // TRANSFERENCIA DESDE COMUNICACIONES O VINCULAR
    if ($transferencia->getOrigentransferenciaid() == 4) { // VINCULADA
      $vinculada = VinculadaPeer::retrieveByPK($transferencia->getVinculadaId());
      $vinculada->setAceptado(2);
      $vinculada->save();
    } else {
      // SI LA TRANSFERENCIA ES ENTRE ARCHIVOS
      // ACTUALIZACION DE LA UNIDAD DOCUMENTAL
      $unidad_documental = UnidadDocumentalPeer::retrieveByPk($transferencia->getUnidaddocumentalId());
      $unidad_documental->setEstadoTransferencia(null);
      $unidad_documental->save();
    }
    //*********************************************************************************
    $transferencia->setMarca(0);
    $transferencia->setObservaciones($this->getRequestParameter('observaciones'));
    $transferencia->save();
  }

  public function envioMailRechazo(Transferencia $transferencia)
  {
    // USUARIO SOLICITA
    $c = new Criteria();
    $c->add(UsuarioTransferenciaPeer::ROLUSUARIOTRANSFERENCIA_ID, 1);
    $c->add(UsuarioTransferenciaPeer::TRANSFERENCIA_ID, $transferencia->getTransferenciaId());
    $usuario_solicita = UsuarioTransferenciaPeer::doSelectOne($c);
    //***********************************************************************
    if ($usuario_solicita->getPrimaryKey()) {
      $transferencia->envioEmail($usuario_solicita->getUsuario());
    }
  }

  public function updateTransferencia(Transferencia $transferencia)
  {
    $transferencia->setMarca(0);
    $transferencia->setEstadotransferenciaId(2);
    $transferencia->setFechaAceptacion(date('Y-m-d G:i:s'));
    $transferencia->save();
  }

  private function transferenciaComunicaciones(Transferencia $transferencia)
  {
    $usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $unidaddocumental_id = $transferencia->getUnidaddocumentalId();
    $total_folios = 1;
    //*********************************************************************************************
    $contenido_documental = new ContenidoUnidadDocumental();
    $contenido_documental->setUnidaddocumentalId($unidaddocumental_id);
    $contenido_documental->setVerificacioncontunidaddocId(2);
    $contenido_documental->setEstadocontenidounidaddocId(1);
    $contenido_documental->setFechaCreacion(date('Y-m-d G:i:s'));
    $contenido_documental->setCreadoPorWeb(1);
    $contenido_documental->setMarca(0);
    $contenido_documental->setSoporteunidaddocumentalId(4);
	  $contenido_documental->setOrigendocumentoId(1); //ORIGEN ELECTRONICO
	  $szfile = 0;
    $exfile = "N/A";
	  //*********************************************************************************************
    $mimetypes = explode(";",ParametroPeer::retrieveByPK(31)->getValortexto());
    //*********************************************************************************************
    $c = new Criteria();
    $c->add(UsuarioTransferenciaPeer::ROLUSUARIOTRANSFERENCIA_ID, 1);
    $c->add(UsuarioTransferenciaPeer::TRANSFERENCIA_ID, $transferencia->getPrimaryKey());
    $usuario_solicita = UsuarioTransferenciaPeer::doSelectOne($c);
    //echo $usuario_solicita->getUsuarioId();
    if ($usuario_solicita->getUsuarioId()){ $contenido_documental->setUsuarioId($usuario_solicita->getUsuarioId()); }
    //*********************************************************************************************
    switch ($transferencia->getOrigentransferenciaid()) {
      case 1: // INTERNA
        $url_registro = ParametroPeer::retrieveByPK(19)->getValortexto();
        $ruta = $url_registro . $transferencia->getCominternaId();
        $total_folios = !empty($transferencia->getComInterna()->getFolios()) ? trim($transferencia->getComInterna()->getFolios()) : 1;
        //*****************************************************************************************
        $dir_raiz = ParametroPeer::retrieveByPk(25)->getValortexto();
        $digit_dir  = ParametroPeer::retrieveByPk(15)->getValortexto();
        $storage_com = $transferencia->getComInterna()->getBasicUrlDigitCom($dir_raiz,$digit_dir);          
        $filename = sprintf("%s.%s",trim($transferencia->getComInterna()->getRadicado()),'pdf');
        foreach ($mimetypes as $format) {
          $filename = sprintf("%s.%s",trim($transferencia->getComInterna()->getRadicado()),$format);
          $targetpath = $storage_com['storage_path'] . DIRECTORY_SEPARATOR . $filename;
          if(file_exists($targetpath)){
            $szfile = filesize($targetpath);
            $exfile = strtoupper($format);
            break;
          }
        }
        //*****************************************************************************************
        $contenido_documental->setDescripcion($transferencia->getCominterna()->getRadicado() . " - " . $transferencia->getCominterna()->getReferencia());
        $contenido_documental->setFolios($total_folios);
        $contenido_documental->setFechaDocumento($transferencia->getComInterna()->getFechaCreacion());
        $contenido_documental->setVinculoRegistro(1);
        $contenido_documental->setRuta($ruta);
        break;
      case 2: // ENTRANTE
        $url_registro = ParametroPeer::retrieveByPK(20)->getValortexto();
        $ruta = $url_registro . $transferencia->getComrecibidaId();
        $total_folios = !empty($transferencia->getComrecibida()->getFolios()) ? trim($transferencia->getComrecibida()->getFolios()) : 1;
        //******************************************************************************************
        $dir_raiz = ParametroPeer::retrieveByPk(27)->getValortexto();
        $digit_dir  = ParametroPeer::retrieveByPk(14)->getValortexto();
        $storage_com = $transferencia->getComrecibida()->getBasicUrlDigitCom($dir_raiz,$digit_dir);          
        $filename = sprintf("%s.%s",trim($transferencia->getComrecibida()->getRadicado()),'pdf');
        foreach ($mimetypes as $format) {
          $filename = sprintf("%s.%s",trim($transferencia->getComrecibida()->getRadicado()),$format);
          $targetpath = $storage_com['storage_path'] . DIRECTORY_SEPARATOR . $filename;
          if(file_exists($targetpath)){
            $szfile = filesize($targetpath);
            $exfile = strtoupper($format);
            break;
          }
        }
        //******************************************************************************************
        $contenido_documental->setDescripcion($transferencia->getComrecibida()->getRadicado() . " - " . $transferencia->getComrecibida()->getAsuntorecibida()->getDescripcion());
        $contenido_documental->setFolios($total_folios);
        $contenido_documental->setFechaDocumento($transferencia->getComRecibida()->getFechaCreacion());
        $contenido_documental->setVinculoRegistro(1);
        $contenido_documental->setRuta($ruta);
        break;
      case 3: // SALIENTE
        $url_registro = ParametroPeer::retrieveByPK(21)->getValortexto();
        $ruta = $url_registro . $transferencia->getComenviadaId();
        $total_folios = !empty($transferencia->getComEnviada()->getFolios()) ? trim($transferencia->getComEnviada()->getFolios()) : 1;
        //******************************************************************************************
        $dir_raiz = ParametroPeer::retrieveByPk(29)->getValortexto();
        $digit_dir  = ParametroPeer::retrieveByPk(13)->getValortexto();
        $storage_com = $transferencia->getComEnviada()->getBasicUrlDigitCom($dir_raiz,$digit_dir);          
        $filename = sprintf("%s.%s",trim($transferencia->getComEnviada()->getRadicado()),'pdf');
        foreach ($mimetypes as $format) {
          $filename = sprintf("%s.%s",trim($transferencia->getComEnviada()->getRadicado()),$format);
          $targetpath = $storage_com['storage_path'] . DIRECTORY_SEPARATOR . $filename;
          if(file_exists($targetpath)){
            $szfile = filesize($targetpath);
            $exfile = strtoupper($format);
            break;
          }
        }
        //*****************************************************************************************
        $contenido_documental->setDescripcion($transferencia->getComenviada()->getRadicado() . " - " . $transferencia->getComenviada()->getAsunto());
        $contenido_documental->setFolios($total_folios);
        $contenido_documental->setFechaDocumento($transferencia->getComEnviada()->getFechaCreacion());
        $contenido_documental->setVinculoRegistro(1);
        $contenido_documental->setRuta($ruta);
        break;
      case 4: // VINCULADA
        $vinculada = VinculadaPeer::retrieveByPK($transferencia->getVinculadaId());
        $vinculada->setAceptado(1);
        $total_folios = !empty($vinculada->getFolios()) ? trim($vinculada->getFolios()) : 1;
        //*****************************************************************************************
        $contenido_documental->setDescripcion($vinculada->getDescripcion());
        $contenido_documental->setFolios($total_folios);
        //*****************************************************************************************
        $unidad_documental = UnidadDocumentalPeer::retrieveByPK($transferencia->getUnidaddocumentalId());
        $expediente_path = $unidad_documental->getBaseUrlAttachment();
        $vinculada_path = $vinculada->getBaseUrlAttachment();
        //$usuario = UsuarioPeer::retrieveByPK($usuario_conectado);
        //*****************************************************************************************
        $directorio_trd = $expediente_path['full_path'];
        $directorio_vinculada = $vinculada_path['full_path'];
        //*****************************************************************************************
        $archivos_upload = preg_split("/[,]+/",trim($vinculada->getRuta()), -1, PREG_SPLIT_NO_EMPTY);
        $cantidad_archivos = 1;
        $diralias_target = "";
        //*****************************************************************************************
        for ($j = 0; $j < $cantidad_archivos; $j++) {
          $current_file = basename($archivos_upload[$j]);
          if ($current_file != "") {
            $diralias_target = $expediente_path['alias_web'] . "/" . $current_file;
            if (file_exists($directorio_vinculada . DIRECTORY_SEPARATOR . $current_file)) {
              copy($directorio_vinculada . DIRECTORY_SEPARATOR. $current_file, $directorio_trd . DIRECTORY_SEPARATOR . $current_file);
              unlink($directorio_vinculada . DIRECTORY_SEPARATOR . $current_file);
			  //***********************************************************************************
			  $info_file = new SplFileInfo($directorio_trd . DIRECTORY_SEPARATOR . $current_file);
			  $szfile = $info_file->getSize();
			  $exfile = strtoupper($info_file->getExtension());
            }
          }
        }
        //*****************************************************************************************
        $contenido_documental->setRuta($diralias_target);
        $vinculada->setRuta($diralias_target);
        //*****************************************************************************************
        $vinculada->save();
        break;
      case 7: //DOCUMENTACION TECNICA
        $url_registro = ParametroPeer::retrieveByPK(44)->getValortexto();
        $ruta = $url_registro . $transferencia->getDocumentacionId();
        $documentacion = DocumentacionPeer::retrieveByPK($transferencia->getDocumentacionId());
        $contenido_documental->setDescripcion($documentacion->getTitulo() . " - " . $documentacion->getCodigoBarras());
        $contenido_documental->setFolios($total_folios);
        $contenido_documental->setFechaDocumento($documentacion->getFechaCreacion());
        $contenido_documental->setVinculoRegistro(1);
        $contenido_documental->setRuta($ruta);
        break;
      case 8: //FACTURAS
        $url_registro = ParametroPeer::retrieveByPK(71)->getValortexto();
        $ruta = $url_registro . $transferencia->getFacturaId();
        $factura = FacturaPeer::retrieveByPK($transferencia->getFacturaId());
        $contenido_documental->setDescripcion($factura->getAsunto() . " - " . $factura->getRadicado());
        $contenido_documental->setFechaDocumento($factura->getFechaRadicado());
        $contenido_documental->setFolios($total_folios);
        $contenido_documental->setVinculoRegistro(1);
        $contenido_documental->setRuta($ruta);
        break;
    }
    //****************************************************************************************
    $total_folios = !empty($total_folios) ? trim($total_folios) : 1;
    $folio_inicial = ContenidoUnidadDocumentalPeer::getMaxFolioFinalByExpDoc($unidaddocumental_id);
    $folio_final = $folio_inicial + ($total_folios - 1);
    //****************************************************************************************
    $contenido_documental->setFolioInicial($folio_inicial);
    $contenido_documental->setFolioFinal($folio_final);
    $contenido_documental->setFuncEncryp("SHA1");
    $contenido_documental->setTipodocumentalId($transferencia->getTipodocumentalId());
    $contenido_documental->setSizeFile($szfile);
    $contenido_documental->setFormatFile($exfile);
    $contenido_documental->save();
    //****************************************************************************************
    $orden_documento = ContenidoUnidadDocumentalPeer::getOrderByDocInExp($unidaddocumental_id);
    $contenido_documental->setOrdenContenido($orden_documento);
    //****************************************************************************************
    $contenido_documental->setValorHuella($contenido_documental->generateValorHuella());
    //****************************************************************************************
    $transferencia->setEstadotransferenciaId(2);
    $transferencia->setFechaAceptacion(date('Y-m-d G:i:s'));
    $transferencia->save();
	  //****************************************************************************************
	  $transferencia->enviarAlertas();
  }

  private function transferenciaArchivos(Transferencia $transferencia, $nueva_ubicacion)
  {
    // SI LA TRANSFERENCIA ES ENTRE ARCHIVOS
    // ACTUALIZACION DE LA UNIDAD DOCUMENTAL
    $unidad_documental = UnidadDocumentalPeer::retrieveByPk($transferencia->getUnidaddocumentalId());
    //********************************************************************************************************
    // capturar tiempos de retencion
    $subserie = SubseriePeer::retrieveByPK($unidad_documental->getSubserieId());
    $paramentro_tvd = ParametroPeer::retrieveByPK(33);
    $fecha_tvd = $paramentro_tvd->getValortexto();
    //********************************************************************************************************
    $unidad_documental->setEstadoTransferencia(null);
    $unidad_documental->setLocalizacionunidaddocumentalId($transferencia->getDestinotransferenciaId());
    //********************************************************************************************************
    switch ($transferencia->getDestinotransferenciaId()) {
      case 1:
        $campo_vencimiento = $unidad_documental->getFechaCierre();
        $unidad_documental->setUbicacionengestion($nueva_ubicacion);
        if ($campo_vencimiento <= $fecha_tvd) {
          $tiempo_retencion = $subserie->getAnosValoracionDocumental();
        } else {
          $tiempo_retencion = $subserie->getAnosEnGestion();
        }
        break;
      case 2:
        $campo_vencimiento = $unidad_documental->getFechaCierre();
        $unidad_documental->setUbicacionencentral($nueva_ubicacion);
        if ($campo_vencimiento <= $fecha_tvd) {
          $tiempo_retencion = $subserie->getAnosValoracionDocumental();
        } else {
          $tiempo_retencion = $subserie->getAnosEnCentral();
        }
        break;
      case 3:
        $campo_vencimiento = $unidad_documental->getFechaCierre();
        $unidad_documental->setUbicacionenhistorico($nueva_ubicacion);
        if ($campo_vencimiento <= $fecha_tvd) {
          $tiempo_retencion = $subserie->getAnosValoracionDocumental();
        } else {
          $tiempo_retencion = $subserie->getAnosEnHistorico();
        }
        break;
    }
    ///////////// FECHA DE VENCIMIENTO CON TABLAS DE RETENCION DOCUMENTAL   
    //list($d, $m, $y) = sfI18N::getDateForCulture($campo_vencimiento, $this->getUser()->getCulture());
    try {
      $date = new DateTime($campo_vencimiento);
      $campo_vencimiento = $date->format('Y-m-d');
      $fechavencimiento   = AddYearsDateTime($campo_vencimiento, $tiempo_retencion);
      $unidad_documental->setFechavencimiento($fechavencimiento);
    } catch (Exception $ex) {
      $unidad_documental->setFechavencimiento(null);
    }
    ////////////// FIN FECHA VENCIMIENTO //////////////////////
    $unidad_documental->save();
  }
}